/**
 * Check nervous system health.
 */
async function checkNervousSystemHealth(): Promise<SubsystemHealth> {
  try {
    const ns = getNervousSystem();
    const health = await ns.getHealth();

    return {
      status: health.status,
      message: `Nervous system ${health.status}`,
      details: {
        totalCalls: health.metrics.totalCalls,
        successRate: health.metrics.successRate,
        degradedModeRate: health.metrics.degradedModeRate,
      },
    };
