}

/**
 * Dependency injection for IntegratedNervousSystem.
 * Allows test injection of callGravitoTool, audit layer, and time functions.
 */
export interface INSDeps {
  /** Gravito governance client (for testing) */
  callGravitoTool?: typeof import('../governance/internal-gravito-client').callGravitoTool;
  /** Audit trail persistence (for testing) */
  audit?: typeof import('../governance/audit-trail-persistence').AuditTrailPersistence;
  /** Time function (for testing) */
  now?: () => number;
  /** Random number generator for deterministic jitter testing (returns [0, 1)) */
  rng?: () => number;
}

export type HealthStatus = 'healthy' | 'degraded' | 'critical';

export interface NervousSystemHealth {
  /** Overall health status */
  status: HealthStatus;
  /** Per-subsystem health checks, each with its own supporting detail */
  subsystems: {
    nervousSystem: {
      status: HealthStatus;
      totalCalls: number;
      successfulCalls: number;
      degradedCalls: number;
    };
    circuitBreakers: {
      status: HealthStatus;
      openCount: number;
      totalBreakers: number;
      tripCount: number;
      metrics: CircuitBreakerMetrics[];
    };
    rateLimiter: {
      status: HealthStatus;
      utilization: number;
      stats: ReturnType<typeof InternalRateLimiter.getRateLimitStats>;
    };
  };
  /** Metrics */
  metrics: {
    totalCalls: number;
    successRate: number;
    averageLatency: number;
    degradedModeRate: number;
    rateLimitUtilization: number;
    fallbackRate: number;
    blockRate: number;
    avgRiskScore: number;
    circuitBreakerTripCount: number;
  };
  /** Point-in-time diagnostic detail (not aggregated rates) */
  diagnostics: {
    circuitBreakerState: string;
    auditTrailEvents: number;
    latencySamples: number;
  };
  /** Timestamp */
  timestamp: number;
}

export interface ExecutionContext {
  /** Correlation ID for tracing */
  correlationId?: string;
  /** API key (for rate limiting) */
  apiKey?: string;
  /** Client IP (for rate limiting) */
  clientIp?: string;
  /** User agent (for logging) */
  userAgent?: string;
  /** Agent plan for auditing */
  agentPlan?: unknown;
}

// ============================================================================
// INTEGRATED NERVOUS SYSTEM
// ============================================================================

export class IntegratedNervousSystem {
  private config: NervousSystemConfig;
  private deps: INSDeps;
  private initialized: boolean = false;
  private totalCalls: number = 0;
  private successfulCalls: number = 0;
  private degradedCalls: number = 0;
  private latencies: number[] = [];

  constructor(config: NervousSystemConfig = {}, deps: INSDeps = {}) {
    this.config = {
      shadowModeEnabled: config.shadowModeEnabled ?? false,
      shadowModeSamplingRate: config.shadowModeSamplingRate ?? 0.1,
      curiosityEngineEnabled: config.curiosityEngineEnabled ?? false,
      invariantMonitoringEnabled: config.invariantMonitoringEnabled ?? true,
      driftDetectionEnabled: config.driftDetectionEnabled ?? true,
    };
    this.deps = deps;
  }

  // ==========================================================================
  // LIFECYCLE
  // ==========================================================================

  /**
   * Initialize the nervous system.
   */
  async init(): Promise<void> {
    if (this.initialized) {
      log.warn('Nervous system already initialized');
      return;
    }

    log.info('Initializing Integrated Nervous System', this.config);

    // Subsystem initialization stubs — log warnings so operators know what is pending
    log.warn('Subsystem not yet wired: Load governance config from DB');
    log.warn('Subsystem not yet wired: Start real-time invariant monitor');
    log.warn('Subsystem not yet wired: Start shadow mode scheduler');
    log.warn('Subsystem not yet wired: Start behavioral drift detector');

    this.initialized = true;
    log.info('Integrated nervous system initialized (stub mode — subsystems pending)');
  }

  /**
   * Get health status.
   */
  async getHealth(): Promise<NervousSystemHealth> {
    const circuitBreakerMetrics = getAllCircuitBreakerMetrics();
    const rateLimitStats = InternalRateLimiter.getRateLimitStats();

    // Circuit breaker health
    const openBreakers = circuitBreakerMetrics.filter(m => m.state === 'OPEN').length;
    const circuitBreakerHealth =
      openBreakers === 0 ? 'healthy' :
      openBreakers <= 2 ? 'degraded' :
      'critical';

    // Rate limiter health
    const rateLimitUtilization = rateLimitStats.globalCount / rateLimitStats.globalLimit;

    // Check per-correlation saturation (critical for Test 1)
    // Uses dedicated method that reads actual per-correlation windows
    const saturationInfo = InternalRateLimiter.getPerCorrelationSaturation();
    const perCorrelationSaturation = saturationInfo.saturated;

    const rateLimiterHealth =
      perCorrelationSaturation ? 'degraded' :
      rateLimitUtilization < 0.7 ? 'healthy' :
      rateLimitUtilization < 0.9 ? 'degraded' :
      'critical';

    // Overall health
    const overallHealth =
      circuitBreakerHealth === 'critical' || rateLimiterHealth === 'critical' ? 'critical' :
      circuitBreakerHealth === 'degraded' || rateLimiterHealth === 'degraded' ? 'degraded' :
      'healthy';

    // Metrics
    const avgLatency = this.latencies.length > 0
      ? this.latencies.reduce((a, b) => a + b, 0) / this.latencies.length
      : 0;

    const successRate = this.totalCalls > 0
      ? this.successfulCalls / this.totalCalls
      : 1;

    const degradedModeRate = this.totalCalls > 0
      ? this.degradedCalls / this.totalCalls
      : 0;

    // Get audit trail stats for additional metrics
    let auditStats = {
      blockRate: 0,
      avgRiskScore: 0,
      totalEvents: 0,
    };
    try {
      const { getAuditTrailStats } = await import('../governance/audit-trail-persistence');
      const stats = await getAuditTrailStats(3600000); // Last 1 hour
      auditStats = {
        blockRate: stats.blockRate,
        avgRiskScore: stats.avgRiskScore,
        totalEvents: stats.totalEvents,
      };
    } catch (err) {
      // Non-blocking: continue with default values
    }

    // Calculate fallback rate
    const fallbackRate = this.totalCalls > 0
      ? (this.degradedCalls / this.totalCalls) * 100
      : 0;

    // Circuit breaker trip count
    const circuitBreakerTripCount = circuitBreakerMetrics.reduce(
      (sum, m) => sum + (m.failures || 0),
      0
    );

    return {
      status: overallHealth,
      subsystems: {
        nervousSystem: {
          status: overallHealth,
          totalCalls: this.totalCalls,
          successfulCalls: this.successfulCalls,
          degradedCalls: this.degradedCalls,
        },
        circuitBreakers: {
          status: circuitBreakerHealth,
          openCount: openBreakers,
          totalBreakers: circuitBreakerMetrics.length,
          tripCount: circuitBreakerTripCount,
          metrics: circuitBreakerMetrics,
        },
        // @ts-ignore — type assignment mismatch (interface drift)
        rateLimiter: {
          status: rateLimiterHealth,
          utilization: rateLimitUtilization,
          stats: rateLimitStats,
        },
      },
      metrics: {
        totalCalls: this.totalCalls,
        successRate: Math.round(successRate * 100) / 100,
        averageLatency: Math.round(avgLatency),
        degradedModeRate: Math.round(degradedModeRate * 100) / 100,
        fallbackRate: Math.round(fallbackRate * 10) / 10,
        blockRate: Math.round(auditStats.blockRate * 10) / 10,
        avgRiskScore: auditStats.avgRiskScore,
        circuitBreakerTripCount,
        rateLimitUtilization: Math.round(rateLimitUtilization * 100) / 100,
      },
      diagnostics: {
        circuitBreakerState: circuitBreakerMetrics[0]?.state || 'CLOSED',
        auditTrailEvents: auditStats.totalEvents,
        latencySamples: this.latencies.length,
      },
      timestamp: Date.now(),
    };
  }

  /**
   * Get health with alerting thresholds.
   */
  async getHealthWithAlerts(): Promise<{
    health: NervousSystemHealth;
    alerts: Array<{
      severity: 'critical' | 'warning' | 'info';
      message: string;
      metric: string;
      value: number;
      threshold: number;
    }>;
  }> {
    const health = await this.getHealth();
    const alerts: Array<{
      severity: 'critical' | 'warning' | 'info';
      message: string;
      metric: string;
      value: number;
      threshold: number;
    }> = [];

    // Fallback rate alert
    if (health.metrics.fallbackRate > 50) {
      alerts.push({
        severity: 'critical',
        message: `Fallback rate is over 50% (${health.metrics.fallbackRate}%)`,
        metric: 'fallbackRate',
        value: health.metrics.fallbackRate,
        threshold: 50,
      });
    }

    // Block rate alert
    if (health.metrics.blockRate > 10) {
      alerts.push({
        severity: 'warning',
        message: `Block rate is over 10% (${health.metrics.blockRate}%)`,
        metric: 'blockRate',
        value: health.metrics.blockRate,
        threshold: 10,
      });
    }

    // Average risk score alert
    if (health.metrics.avgRiskScore > 60) {
      alerts.push({
        severity: 'warning',
        message: `Average risk score is over 60 (${health.metrics.avgRiskScore})`,
        metric: 'avgRiskScore',
        value: health.metrics.avgRiskScore,
        threshold: 60,
      });
    }

    // Circuit breaker trip count alert
    if (health.metrics.circuitBreakerTripCount > 100) {
      alerts.push({
        severity: 'critical',
        message: `Circuit breaker trip count is over 100 (${health.metrics.circuitBreakerTripCount})`,
        metric: 'circuitBreakerTripCount',
        value: health.metrics.circuitBreakerTripCount,
        threshold: 100,
      });
    }

    return { health, alerts };
  }

  /**
   * Shut down the nervous system.
   */
  async shutdown(): Promise<void> {
    if (!this.initialized) {
      return;
    }

    log.info('Shutting down Integrated Nervous System');

    // Subsystems use server-level graceful shutdown via process signal handlers

    this.initialized = false;
    log.info('Integrated Nervous System shut down');
  }

  // ==========================================================================
  // PERCEPTION LAYER
  // ==========================================================================

  /**
   * Normalize and validate the input request.
   */
  private perceive(input: Record<string, unknown>, context: ExecutionContext): GovernanceRequest {
    try {
      const normalized = GovernanceRequestNormalizer.normalize(input);
      // Input validated at tRPC router layer via Zod schemas
      return normalized as GovernanceRequest;
    } catch (err: unknown) {
      log.warn(`Invalid governance request: ${err instanceof Error ? err.message : String(err)}`, { input, context });
      throw new Error('Invalid governance request');
    }
  }

  /**
   * Check rate limits.
   */
  private checkRateLimits(context: ExecutionContext): void {
    const correlationId = context.correlationId ?? context.apiKey ?? context.clientIp;
    if (!correlationId) {
      return;
    }

    const { allowed } = InternalRateLimiter.checkRateLimit(correlationId);
    if (!allowed) {
      throw new Error('Rate limit exceeded');
    }
  }

  // ==========================================================================
  // PROCESSING LAYER
  // ==========================================================================

  /**
   * Execute the core governance logic.
   */
  private async process(request: GovernanceRequest): Promise<GovernanceResponse> {
    const startTime = Date.now();
    this.totalCalls = (this.totalCalls ?? 0) + 1;

    try {
      // Use injected Gravito client if available (for testing)
      const callGravito = this.deps.callGravitoTool || (await import('../governance/internal-gravito-client')).callGravitoTool;

      const reviewPayload: Record<string, unknown> = {
        content: request.content,
        surfaceType: request.surfaceType,
        artifactType: request.artifactType,
      };
      if (request.mode != null) reviewPayload.mode = request.mode;
      if (request.context != null) reviewPayload.context = request.context;
      if (request.correlationId != null) reviewPayload.correlationId = request.correlationId;

      const breakerName = `gov.${request.surfaceType}`;

      const response = await withCircuitBreaker(
        {
          name: breakerName,
          failureThreshold: 3,
          recoveryTimeout: 30_000,
          callTimeout: 60_000,
        },
        async () => {
          let lastError: Error | null = null;
          for (let i = 0; i < 3; i++) {
            try {
              const raw = await callGravito('reviewContent', reviewPayload, {
                retries: 0,
                caller: 'integrated-nervous-system',
              });
              if (raw.success && raw.result != null) {
                return raw.result as GovernanceResponse;
              }
              lastError = new Error(raw.error || 'reviewContent returned no result');
            } catch (err: unknown) {
              lastError = err instanceof Error ? err : new Error(String(err));
            }
            if (i < 2) {
              const backoffMs = 100 * Math.pow(2, i);
              await new Promise(resolve => setTimeout(resolve, backoffMs));
            }
          }

          throw lastError || new Error('Governance call failed after retries');
        },
        () => DeterministicFallback.generateDeterministicFallback(request, 'circuit_breaker_open')
      );

      response.elapsedMs = Date.now() - startTime;

      // Record success/degraded metrics (totalCalls already incremented above)
      // Use defensive pattern for atomic increment
      if (!response.degradedMode) {
        this.successfulCalls = (this.successfulCalls ?? 0) + 1;
      } else {
        this.degradedCalls = (this.degradedCalls ?? 0) + 1;
      }

      const latency = Date.now() - startTime;
      this.latencies.push(latency);
      if (this.latencies.length > 100) {
        this.latencies = this.latencies.slice(-100);
      }

      return response;
    } catch (err) {
      // totalCalls already incremented at start of method
      throw err;
    } finally {
      // Record timestamp for observability
      // (metrics.lastCallTimestamp could be added here if needed)
    }
  }

  // ==========================================================================
  // ACTION LAYER
  // ==========================================================================

  /**
   * Execute pre-execution hooks.
   */
  private async preExecutionHooks(
    request: GovernanceRequest,
    context: ExecutionContext
  ): Promise<void> {
    // Pre-gate invariant enforcement
    if (this.config.invariantMonitoringEnabled) {
      // @ts-ignore — argument type mismatch (interface drift)
      const { checkInvariants } = await import('../governance/invariant-enforcement');
      // @ts-ignore — TS2345 type mismatch
      await checkInvariants(request, 'pre-gate');
    }

    // Plan auditing (if agent plan is present)
    if (context.agentPlan && this.config.planAuditingEnabled) {
      // @ts-ignore — module export mismatch
      const { auditAgentPlan } = await import('../governance/agent-plan-auditor');
      await auditAgentPlan(context.agentPlan, request);
    }

    // Confidence scoring
    if (this.config.confidenceScoringEnabled) {
      // @ts-ignore — module export mismatch
      const { scoreConfidence } = await import('../governance/confidence-scoring');
      await scoreConfidence(request);
    }
  }

  /**
   * Execute post-execution hooks.
   */
  private async postExecutionHooks(
    request: GovernanceRequest,
    response: GovernanceResponse,
    context: ExecutionContext
  ): Promise<void> {
    // Post-gate invariant enforcement
    if (this.config.invariantMonitoringEnabled) {
      const { checkInvariants } = await import('../governance/invariant-enforcement');
      // @ts-ignore — argument count mismatch (interface drift)
      await checkInvariants(request, 'post-gate', response);
    }

    // Reversibility tracking
    if (this.config.reversibilityEnabled && response.blockRelease) {
      // @ts-ignore — module export mismatch
      const { trackReversibility } = await import('../governance/execution-reversibility');
      await trackReversibility(request, response, context);
    }

    // Behavioral drift detection
    if (this.config.driftDetectionEnabled && request.surfaceType) {
      // Use injected audit dependency if provided (for testing), otherwise import real implementation
      const audit = this.deps.audit || (await import('../governance/audit-trail-persistence')).AuditTrailPersistence;
      const driftResult = await audit.detectBehavioralDrift(request.surfaceType);
      if (driftResult.driftDetected) {
        // @ts-ignore — undefined reference
        governanceLog.warn(
          `[IntegratedNervousSystem] Behavioral drift detected for ${request.surfaceType}: ` +
          `recent risk ${driftResult.recentAvgRiskScore} vs historical ${driftResult.historicalAvgRiskScore} ` +
          `(drift score: ${driftResult.driftScore})`
        );
      }
    }

    // Transparency layer logging
    if (this.config.transparencyLayerEnabled) {
      // @ts-ignore — module export mismatch
      const { logToTransparencyLayer } = await import('../governance/transparency-layer');
      await logToTransparencyLayer({
        request,
        response,
        context,
        timestamp: Date.now(),
      });
    }
  }

  // ==========================================================================
  // REFLECTION LAYER
  // ==========================================================================

  /**
   * Log execution for audit trail.
   */
  private async reflect(
    request: GovernanceRequest,
    response: GovernanceResponse,
    context: ExecutionContext
  ): Promise<void> {
    // NOTE (P2a): the previous audit-trail write here dynamically imported
    // `logGovernanceEvent` from '../governance/governance-telemetry', which does
    // NOT export it (the writer lives in ../governance/audit-trail-persistence).
    // The import resolved to `undefined`, so the subsequent call threw at
    // runtime and was silently swallowed by the catch — a dead, never-successful
    // write. The broken import+call is removed here to un-break this path.
    // Wiring the real governance_audit_trail writer to live traffic is a
    // separate decision (P2b) and intentionally NOT done in this packet.

    // Update metrics with defensive atomic pattern
    this.totalCalls = (this.totalCalls ?? 0) + 1;
    if (response.degradedMode) {
      this.degradedCalls = (this.degradedCalls ?? 0) + 1;
    } else {
      this.successfulCalls = (this.successfulCalls ?? 0) + 1;
    }

    // Trigger alerts if needed
    if (response.blockRelease && response.riskScore > 80) {
      // @ts-ignore — argument type mismatch (interface drift)
      try {
        const { sendSlackGovernanceAlert } = await import('../governance/slack-governance-alerts');
        // @ts-ignore — TS2345 type mismatch
        await sendSlackGovernanceAlert('critical_block', {
          surfaceType: request.surfaceType,
          riskScore: response.riskScore,
          correlationId: request.correlationId,
          gravitoRunId: response.gravitoRunId,
        });
      } catch (err: unknown) {
        log.warn(`Failed to send alert: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  }

  // ==========================================================================
  // PUBLIC API
  // ==========================================================================

  /**
   * Execute governance review.
   * 
   * This is the main entry point for all governance operations.
   */
  async review(
    input: Record<string, unknown>,
    context: ExecutionContext = {}
  ): Promise<GovernanceResponse> {
    if (!this.initialized) {
      await this.init();
    }

    // Perception: Normalize and validate
    const request = this.perceive(input, context);

    // Perception: Check rate limits
    this.checkRateLimits(context);

    // Action: Pre-execution hooks
    await this.preExecutionHooks(request, context);

    // Processing: Execute governance
    const response = await this.process(request);

    // Action: Post-execution hooks
    await this.postExecutionHooks(request, response, context);

    // Reflection: Log for audit trail
    await this.reflect(request, response, context);

    return response;
  }

  /**
   * Get current configuration.
   */
  getConfig(): NervousSystemConfig {
    return { ...this.config };
  }

  /**
   * Update configuration (hot-reload).
   */
  async updateConfig(updates: Partial<NervousSystemConfig>): Promise<void> {
    this.config = { ...this.config, ...updates };
    log.info('Nervous system config updated', this.config);
  }
}

// ============================================================================
// SINGLETON INSTANCE
// ============================================================================

let instance: IntegratedNervousSystem | null = null;

/**
 * Get the singleton nervous system instance.
 */
export function getNervousSystem(): IntegratedNervousSystem {
  if (!instance) {
    instance = new IntegratedNervousSystem();
  }
  return instance;
}

/**
 * Reset the singleton instance (for testing).
 */
export function resetNervousSystem(): void {
  if (instance) {
    instance.shutdown().catch((err: unknown) => {
      log.error(`Error shutting down nervous system: ${err instanceof Error ? err.message : String(err)}`);
    });
  }
  instance = null;
}

// ============================================================================
// EXPORTS
// ============================================================================

export default IntegratedNervousSystem;

