    : 0;

  // Circuit breaker trip count
  const circuitBreakerTripCount = circuitBreakerMetrics.reduce(
    (sum, m) => sum + (m.failures || 0),
    0
  );

  return {
    status: overallHealth,
    subsystems: {
      nervousSystem: {
        status: overallHealth,
        totalCalls: this.totalCalls,
        successfulCalls: this.successfulCalls,
        degradedCalls: this.degradedCalls,
      },
      circuitBreakers: {
        status: circuitBreakerHealth,
        openCount: openBreakers,
        totalBreakers: circuitBreakerMetrics.length,
        tripCount: circuitBreakerTripCount,
        metrics: circuitBreakerMetrics,
      },
      rateLimiter: {
        status: rateLimiterHealth,
        utilization: rateLimitUtilization,
        stats: rateLimitStats,
      },
    },
    metrics: {
      totalCalls: this.totalCalls,
      successRate: Math.round(successRate * 100) / 100,
      averageLatency: Math.round(avgLatency),
      degradedModeRate: Math.round(degradedModeRate * 100) / 100,
      fallbackRate: Math.round(fallbackRate * 10) / 10,
      blockRate: Math.round(auditStats.blockRate * 10) / 10,
      avgRiskScore: auditStats.avgRiskScore,
      circuitBreakerTripCount,
      rateLimitUtilization: Math.round(rateLimitUtilization * 100) / 100,
    },
    diagnostics: {
      circuitBreakerState: circuitBreakerMetrics[0]?.state || 'CLOSED',
      auditTrailEvents: auditStats.totalEvents,
      latencySamples: this.latencies.length,
    },
    timestamp: Date.now(),
  };
}

    CONFIG.WINDOW_MS = updates.windowMs;
  }

  log.info(`Rate limit config updated:`, CONFIG);
}

// ============================================================================
// EXPORTS
// ============================================================================

export const InternalRateLimiter = {
  checkRateLimit,
  recordGovernanceCall,
  getRateLimitStats,
  getCorrelationStats,
  getPerCorrelationSaturation,
  resetRateLimits,
  updateConfig,
  CONFIG,
};

