    // Generate diagnostics
    const diagnostics = generateDiagnostics(subsystems);

    // Collect metrics
    const circuitBreakerMetrics = getAllCircuitBreakerMetrics();
    const rateLimitStats = InternalRateLimiter.getRateLimitStats();
    const circuitBreakerStates: Record<string, string> = {};
    for (const metric of circuitBreakerMetrics) {
      circuitBreakerStates[metric.name] = metric.state;
    }

    const ns = getNervousSystem();
    const nsHealth = await ns.getHealth();

    const response: HealthResponse = {
      status: overallStatus,
      timestamp: Date.now(),
      subsystems,
      diagnostics,
      metrics: {
        totalCalls: nsHealth.metrics.totalCalls,
        successRate: nsHealth.metrics.successRate,
        degradedRate: nsHealth.metrics.degradedModeRate,
        averageLatency: nsHealth.metrics.averageLatency,
        circuitBreakerStates,
        rateLimitUtilization: rateLimitStats.globalCount / rateLimitStats.globalLimit,
      },
    };

    res.json(response);
  } catch (err) {
    log.error(`Governance health check failed: ${err}`);
    res.status(500).json({
      status: 'critical',
      timestamp: Date.now(),
      error: String(err),
    });
  }
});

